#!/usr/bin/env python3
"""Mini-Core: parser, monotype checker and evaluator."""
import operator
import re
import sys

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(1000000)


class ParseError(Exception):
    pass


class BadType(Exception):
    pass


# The trie of type equations is represented as a graph of equivalence
# classes. A class is unconstrained ('?'), Int, Bool or an arrow.
class Type:
    __slots__ = ('tag', 'a', 'b', 'parent')

    def __init__(self, tag='?', a=None, b=None):
        self.tag = tag
        self.a = a
        self.b = b
        self.parent = self


INT = Type('Int')
BOOL = Type('Bool')


def root(t):
    while t.parent is not t:
        t.parent = t.parent.parent
        t = t.parent
    return t


class Types:
    def __init__(self):
        self.arrows = []

    def arrow(self, a, b):
        t = Type('->', a, b)
        self.arrows.append(t)
        return t

    @staticmethod
    def unify(x, y):
        pending = [(x, y)]
        while pending:
            x, y = pending.pop()
            x = root(x)
            y = root(y)
            if x is y:
                continue
            if x.tag == '?':
                x.parent = y
            elif y.tag == '?':
                y.parent = x
            elif x.tag == y.tag == '->':
                x.parent = y
                pending.append((x.a, y.a))
                pending.append((x.b, y.b))
            else:
                raise BadType

    def check_finite(self):
        # A deferred occurs check. Even types of discarded subexpressions
        # must be finite. Sharing of non-cyclic subtrees is fine.
        done = set()
        active = set()
        for t in self.arrows:
            t = root(t)
            if t in done:
                continue
            stack = [(t, False)]
            while stack:
                t, exiting = stack.pop()
                if exiting:
                    active.remove(t)
                    done.add(t)
                elif t.tag == '->' and t not in done:
                    if t in active:
                        raise BadType
                    active.add(t)
                    stack.extend(((t, True), (root(t.b), False), (root(t.a), False)))


LEX = re.compile(r'\s+|--[^\r\n]*|[A-Za-z_][A-Za-z0-9_]*|[0-9]+|->|//|==|[()/*+%<=:\-]|(.)', re.ASCII)
KEYWORDS = set('let rec in if then else'.split())
INVALID = {'match', 'with', 'type', 'forall', '_'}
UPPER = {'Int', 'Bool', 'True', 'False'}


def lex(data):
    try:
        text = data.decode('ascii')
    except UnicodeDecodeError:
        raise ParseError from None
    tokens = []
    for m in LEX.finditer(text):
        t = m[0]
        if t[0] in ' \r\n\v\t\f' or t.startswith('--'):
            continue
        if m[1] or t in INVALID or ('A' <= t[0] <= 'Z' and t not in UPPER):
            raise ParseError
        tokens.append(t)
    tokens.append('')
    return tokens


def is_name(t):
    return bool(t) and ('a' <= t[0] <= 'z' or t[0] == '_') and t not in KEYWORDS


class Parser:
    def __init__(self, data, types):
        self.tokens = lex(data)
        self.i = 0
        self.t = self.tokens[0]
        self.types = types

    def take(self):
        t = self.t
        self.i += 1
        self.t = self.tokens[self.i]
        return t

    def accept(self, t):
        if self.t == t:
            self.take()
            return True
        return False

    def need(self, t):
        if not self.accept(t):
            raise ParseError

    def name(self):
        if not is_name(self.t):
            raise ParseError
        return self.take()

    def parse(self):
        e = self.expr()
        if self.t != '':
            raise ParseError
        return e

    def typ(self):
        if self.accept('Int'):
            a = INT
        elif self.accept('Bool'):
            a = BOOL
        elif self.accept('('):
            a = self.typ()
            self.need(')')
        else:
            raise ParseError
        if self.accept('->'):
            return self.types.arrow(a, self.typ())
        return a

    def expr(self):
        if self.accept('/'):
            x = self.name()
            self.need('->')
            return ('lam', x, self.expr())
        if self.accept('if'):
            c = self.expr()
            self.need('then')
            a = self.expr()
            self.need('else')
            return ('if', c, a, self.expr())
        if self.accept('let'):
            rec = self.accept('rec')
            x = self.name()
            ann = self.typ() if self.accept(':') else None
            if rec and ann is None:
                raise ParseError
            self.need('=')
            a = self.expr()
            if rec and a[0] != 'lam':
                raise ParseError
            self.need('in')
            return ('rec' if rec else 'let', x, ann, a, self.expr())
        a = self.add()
        if self.t in ('<', '=='):
            return (self.take(), a, self.add())
        return a

    def add(self):
        a = self.mul()
        while self.t in ('+', '-'):
            a = (self.take(), a, self.mul())
        return a

    def mul(self):
        a = self.app()
        while self.t in ('*', '//', '%'):
            a = (self.take(), a, self.app())
        return a

    def app(self):
        a = self.atom()
        if a is None:
            raise ParseError
        while (b := self.atom()) is not None:
            a = ('app', a, b)
        return a

    def atom(self):
        t = self.t
        if self.accept('('):
            a = self.expr()
            if self.accept(':'):
                a = ('ann', a, self.typ())
            self.need(')')
            return a
        if is_name(t):
            return ('var', self.take())
        if t.isdigit():
            return ('lit', int(self.take()))
        if t in ('True', 'False'):
            return ('lit', self.take() == 'True')
        return None


class Checker:
    def __init__(self, types):
        self.types = types
        self.env = {}

    def scoped(self, x, t, body):
        prev = self.env.get(x)
        self.env[x] = t
        result = self.infer(body)
        self.env[x] = prev
        return result

    def infer(self, e):
        k = e[0]
        unify = self.types.unify
        if k == 'lit':
            return INT if type(e[1]) is int else BOOL
        if k == 'var':
            t = self.env.get(e[1])
            if t is None:
                raise BadType
            return t
        if k == 'lam':
            a = Type()
            return self.types.arrow(a, self.scoped(e[1], a, e[2]))
        if k == 'app':
            f = self.infer(e[1])
            arg = self.infer(e[2])
            res = Type()
            unify(f, self.types.arrow(arg, res))
            return res
        if k == 'if':
            unify(self.infer(e[1]), BOOL)
            a = self.infer(e[2])
            unify(a, self.infer(e[3]))
            return a
        if k == 'ann':
            unify(self.infer(e[1]), e[2])
            return e[2]
        if k in ('let', 'rec'):
            _, x, ann, a, body = e
            t = self.scoped(x, ann, a) if k == 'rec' else self.infer(a)
            if ann is not None:
                unify(t, ann)
            return self.scoped(x, t, body)
        unify(self.infer(e[1]), INT)
        unify(self.infer(e[2]), INT)
        return BOOL if k in ('<', '==') else INT


OPS = {'+': operator.add, '-': operator.sub, '*': operator.mul,
       '//': operator.floordiv, '%': operator.mod, '<': operator.lt, '==': operator.eq}


def evaluate(e, env=None):
    while True:
        k = e[0]
        if k == 'lit':
            return e[1]
        if k == 'var':
            while env[0] != e[1]:
                env = env[2]
            return env[1]
        if k == 'lam':
            return e, env
        if k == 'app':
            f, outer = evaluate(e[1], env)
            env = (f[1], evaluate(e[2], env), outer)
            e = f[2]
        elif k == 'if':
            e = e[2] if evaluate(e[1], env) else e[3]
        elif k == 'ann':
            e = e[1]
        elif k in ('let', 'rec'):
            if k == 'let':
                env = (e[1], evaluate(e[3], env), env)
            else:
                env = [e[1], None, env]
                env[1] = (e[3], env)
            e = e[4]
        else:
            return OPS[k](evaluate(e[1], env), evaluate(e[2], env))


def run(path):
    with open(path, 'rb') as f:
        data = f.read()
    types = Types()
    e = Parser(data, types).parse()
    Checker(types).infer(e)
    types.check_finite()
    value = evaluate(e)
    return '<function>' if isinstance(value, tuple) else value


if __name__ == '__main__':
    try:
        print(run(sys.argv[2]))
    except ParseError:
        print('ParseError')
        sys.exit(1)
    except BadType:
        print('TypeError')
        sys.exit(1)
    except ZeroDivisionError:
        print('RuntimeError')
        sys.exit(1)

# Operands live on one value stack, separate from local bindings and
# return addresses. Every compiled expression leaves exactly one result.
(CONST, LOCAL, FREE, BIND, UNBIND, CLOSURE, JFALSE, JUMP, BINARY,
 CALL, TAIL, RETURN) = range(12)


class Compiler:
    """Compile one lambda (or the main expression) in its lexical scope."""

    def __init__(self, parent=None, param=None, recursive=None):
        self.code = []
        self.parent = parent
        self.locals = {}
        # Functions have two initial slots: argument and closure itself.
        self.depth = 0 if parent is None else 2
        if recursive is not None:
            self.locals[recursive] = 1
        if param is not None:
            self.locals[param] = 0
        self.free = {}
        self.capture_slots = []

    def resolve(self, x):
        # Local slots >= 0; captured slots encoded as bitwise complements.
        if x in self.locals:
            return self.locals[x]
        if x not in self.free:
            slot = self.parent.resolve(x)
            self.free[x] = ~len(self.capture_slots)
            self.capture_slots.append(slot)
        return self.free[x]

    def load(self, slot):
        self.code.append((LOCAL, slot) if slot >= 0 else (FREE, ~slot))

    def function(self, e, recursive=None):
        fn = Compiler(self, e[1], recursive)
        fn.expr(e[2], True)
        fn.code.append((RETURN, None))
        # Capture only the values that may be read; no mutable environment
        # shared with the creator. A recursive reference is local slot 1.
        if fn.capture_slots:
            for slot in fn.capture_slots:
                self.load(slot)
            self.code.append((CLOSURE, (fn.code, len(fn.capture_slots))))
        else:
            self.code.append((CONST, (fn.code, ())))

    def expr(self, e, tail):
        code = self.code
        k = e[0]
        if k == 'lit':
            code.append((CONST, e[1]))
        elif k == 'var':
            self.load(self.resolve(e[1]))
        elif k == 'lam':
            self.function(e)
        elif k == 'ann':
            self.expr(e[1], tail)
        elif k == 'app':
            self.expr(e[1], False)
            self.expr(e[2], False)
            code.append((TAIL if tail else CALL, None))
        elif k in ('rec', 'let'):
            _, name, _, rhs, body = e
            if k == 'rec':
                self.function(rhs, name)
            else:
                self.expr(rhs, False)
            code.append((BIND, None))
            prev = self.locals.get(name)
            self.locals[name] = self.depth
            self.depth += 1
            self.expr(body, tail)
            self.depth -= 1
            if prev is None:
                del self.locals[name]
            else:
                self.locals[name] = prev
            if not tail:
                code.append((UNBIND, None))
        elif k == 'if':
            self.expr(e[1], False)
            branch = len(code)
            code.append(None)
            self.expr(e[2], tail)
            end = len(code)
            code.append(None)
            code[branch] = (JFALSE, len(code))
            self.expr(e[3], tail)
            code[end] = (JUMP, len(code))
        else:
            self.expr(e[1], False)
            self.expr(e[2], False)
            code.append((BINARY, OPS[k]))


def execute(code):
    stack = []
    frames = []
    ip = 0
    local = []
    free = ()
    while True:
        op, a = code[ip]
        ip += 1
        if op == LOCAL:
            stack.append(local[a])
        elif op == CONST:
            stack.append(a)
        elif op == BINARY:
            rhs = stack.pop()
            stack[-1] = a(stack[-1], rhs)
        elif op == FREE:
            stack.append(free[a])
        elif op == JFALSE:
            if not stack.pop():
                ip = a
        elif op == JUMP:
            ip = a
        elif op == CALL or op == TAIL:
            if op == CALL:
                frames.append((code, ip, local, free))
            arg = stack.pop()
            closure = stack.pop()
            local = [arg, closure]
            code, free = closure
            ip = 0
        elif op == RETURN:
            if not frames:
                return stack.pop()
            code, ip, local, free = frames.pop()
        elif op == BIND:
            local.append(stack.pop())
        elif op == UNBIND:
            local.pop()
        else:  # CLOSURE (code, number of captures on stack, always > 0)
            body, n = a
            closure = (body, stack[-n:])
            del stack[-n:]
            stack.append(closure)


def evaluate(e):
    compiler = Compiler()
    compiler.expr(e, True)
    compiler.code.append((RETURN, None))
    return execute(compiler.code)

