"""Differential tests on small terms, including higher-order well-typed terms.

Generate independent surface trees and pretty-print. Compute the expected
outcome using substitutions + an immediate occurs check and a direct evaluator.
Run the implementation in-process to keep the suite fast.
"""
from pathlib import Path
import random
import runpy
import sys
import operator

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
mc = runpy.run_path(str(ROOT / 'minicore'))
r = random.Random(50427)
I, B = 'Int', 'Bool'
names = ['x', 'x', 'z', '__', '_2', 'thenA', 'a0', 'xYz']
ops = {'+': operator.add, '-': operator.sub, '*': operator.mul, '//': operator.floordiv, '%': operator.mod, '<': operator.lt, '==': operator.eq}


def typ():
    return r.choice([I, B, (I, I), (B, I), (I, B), ((I, I), (I, I))])


def term(depth, t, env):
    if depth <= 0 or r.randrange(7) == 0:
        variables = [k for k, v in env.items() if v == t]
        if variables and r.randrange(4) != 0:
            return ('var', r.choice(variables))
        if t == I:
            return ('lit', r.randrange(5))
        if t == B:
            return ('lit', bool(r.randrange(2)))
        x = r.choice(names)
        return ('lam', x, term(0, t[1], {**env, x: t[0]}))
    depth -= 1
    k = r.randrange(9)
    if k == 0:
        return ('if', term(depth, B, env), term(depth, t, env), term(depth, t, env))
    if k == 1:
        return ('ann', term(depth, t, env), t)
    if k in (2, 3, 4):
        x, arg = r.choice(names), typ()
        body = term(depth, t, {**env, x: arg})
        val = term(depth, arg, env)
        if k == 2:
            return ('app', ('lam', x, body), val)
        return ('let', x, arg if k == 3 else None, val, body)
    if k == 5:
        arg = typ()
        return ('app', term(depth, (arg, t), env), term(depth, arg, env))
    if isinstance(t, tuple):
        x = r.choice(names)
        return ('lam', x, term(depth, t[1], {**env, x: t[0]}))
    return (r.choice(['+', '-', '*', '//', '%'] if t == I else ['<', '==']), term(depth, I, env), term(depth, I, env))


def type_text(t):
    if isinstance(t, tuple):
        return '(' + type_text(t[0]) + '->' + type_text(t[1]) + ')'
    return t


def pretty(e):
    k = e[0]
    if k == 'lit':
        return str(e[1])
    if k == 'var':
        return e[1]
    if k in ops:
        text = f'{pretty(e[1])} {k} {pretty(e[2])}'
    if k == 'app':
        text = f'{pretty(e[1])} {pretty(e[2])}'
    if k == 'if':
        text = f'if {pretty(e[1])} then {pretty(e[2])} else {pretty(e[3])}'
    if k == 'ann':
        text = f'{pretty(e[1])}:{type_text(e[2])}'
    if k == 'lam':
        text = f'/{e[1]}->{pretty(e[2])}'
    if k == 'let':
        ann = '' if e[2] is None else ':' + type_text(e[2])
        text = f'let {e[1]}{ann}={pretty(e[3])} in {pretty(e[4])}'
    return '(' + text + ')'


def mutate(e):
    # Change a random subexpression, preserving syntax but usually not types.
    args = [j for j in range(1, len(e)) if isinstance(e[j], tuple) and not (e[0] in ('ann','let') and j == 2)]
    if args and r.randrange(3):
        j = r.choice(args)
        return (*e[:j], mutate(e[j]), *e[j+1:])
    x = r.choice(names)
    return r.choice([('var', x), ('lam', x, ('var', x)), ('lit', True), ('lit', 3), ('app', ('var', x), ('var', x))])


class Mismatch(Exception):
    pass


def refcheck(e):
    subst = {}

    def walk(t):
        while type(t) is object and t in subst:
            t = subst[t]
        return t

    def occurs(v, t):
        t = walk(t)
        return t is v or (isinstance(t, tuple) and any(occurs(v, a) for a in t))

    def equal(t, u):
        t, u = walk(t), walk(u)
        if t == u:
            return
        if type(u) is object:
            t, u = u, t
        if type(t) is object:
            if occurs(t, u):
                raise Mismatch
            subst[t] = u
        elif isinstance(t, tuple) and isinstance(u, tuple):
            equal(t[0], u[0])
            equal(t[1], u[1])
        else:
            raise Mismatch

    def infer(e, env):
        k = e[0]
        if k == 'lit':
            return I if type(e[1]) is int else B
        if k == 'var':
            if e[1] not in env:
                raise Mismatch
            return env[e[1]]
        if k == 'lam':
            t = object()
            return t, infer(e[2], {**env, e[1]: t})
        if k == 'app':
            f, a, result = infer(e[1], env), infer(e[2], env), object()
            equal(f, (a, result))
            return result
        if k == 'let':
            t = infer(e[3], env)
            if e[2] is not None:
                equal(t, e[2])
            return infer(e[4], {**env, e[1]: t})
        if k == 'ann':
            equal(infer(e[1], env), e[2])
            return e[2]
        if k == 'if':
            equal(infer(e[1], env), B)
            t = infer(e[2], env)
            equal(t, infer(e[3], env))
