"""Lower a small Mini-Core bytecode program to a loop over basic blocks.

This removes interpreter dispatch from the interior of each block. The same
explicit operand and continuation stacks implement calls, including tail
calls, so native call depth does not depend on execution depth. For large
inputs keep bytecode form to bound compilation time and dispatch overhead.
"""
from mcvm import (CONST, LOCAL, FREE, BIND, UNBIND, CLOSURE, JFALSE, JUMP,
                  BINARY, CALL, TAIL, RETURN, OPS)

OP_TEXT = {v: k for k, v in OPS.items()}
LIMIT = 256


def lower(main):
    """Return an executable block loop, or None to use ordinary bytecode."""
    # Flatten the tree of code objects to a single address space. A closure
    # in this representation stores its entry address instead of a code list.
    codes = [main]
    base = {}
    size = 0
    for code in codes:
        base[id(code)] = size
        size += len(code)
        if size > LIMIT:
            return None
        for op, a in code:
            if op == CLOSURE or (op == CONST and type(a) is tuple):
                codes.append(a[0])
    if len(codes) == 1:
        return None

    source = ['def program():', '    s = []', '    frames = []',
              '    local = []', '    free = ()', '    pc = 0', '    while True:']
    constants = []
    for code in codes:
        start = base[id(code)]
        # All destinations of transfers (including saved return addresses)
        # start blocks, as do all instructions following a control transfer.
        cuts = {0, len(code)}
        for i, (op, a) in enumerate(code):
            if op in (JUMP, JFALSE):
                cuts.add(a)
            if op in (JUMP, JFALSE, CALL, TAIL, RETURN):
                cuts.add(i+1)
        cuts = sorted(cuts)
        for left, right in zip(cuts, cuts[1:]):
            test = 'if' if start+left == 0 else 'elif'
            source.append(f'        {test} pc == {start+left}:')
            block = []
            for op, a in code[left:right]:
                if op == LOCAL:
                    block.append(f's.append(local[{a}])')
                elif op == FREE:
                    block.append(f's.append(free[{a}])')
                elif op == CONST:
                    value = (base[id(a[0])], ()) if type(a) is tuple else a
                    block.append(f's.append(K[{len(constants)}])')
                    constants.append(value)
                elif op == BINARY:
                    block.extend(('rhs = s.pop()', f's[-1] = s[-1] {OP_TEXT[a]} rhs'))
                elif op == BIND:
                    block.append('local.append(s.pop())')
                elif op == UNBIND:
                    block.append('local.pop()')
                elif op == CLOSURE:
                    body, n = a
                    block.append(f's[-{n}:] = [({base[id(body)]}, s[-{n}:])]')
                elif op == JFALSE:
                    block.append(f'pc = {start+right} if s.pop() else {start+a}')
                elif op == JUMP:
                    block.append(f'pc = {start+a}')
                elif op == RETURN:
                    block.extend(('if not frames: return s.pop()', 'pc, local, free = frames.pop()'))
                else:  # CALL or TAIL
                    if op == CALL:
                        block.append(f'frames.append(({start+right}, local, free))')
                    block.extend(('arg = s.pop()', 'closure = s.pop()', 'pc, free = closure', 'local = [arg, closure]'))
            if op not in (JFALSE, JUMP, RETURN, CALL, TAIL):
                block.append(f'pc = {start+right}')
            source.extend('            ' + line for line in block)

    # No user-supplied text is used as Python syntax: operands in the
    # templates above are compiler indices and operators from a fixed table.
    ns = {'K': constants, '__builtins__': {}}
    exec('\n'.join(source), ns)
    return ns['program']

