"""Mini-Core bytecode compiler and iterative evaluator."""
import operator

OPS = {'+': operator.add, '-': operator.sub, '*': operator.mul,
       '//': operator.floordiv, '%': operator.mod, '<': operator.lt, '==': operator.eq}

# Operands live on one value stack, separate from local bindings and
# return addresses. Every compiled expression leaves exactly one result.
(CONST, LOCAL, FREE, BIND, UNBIND, CLOSURE, JFALSE, JUMP, BINARY,
 CALL, TAIL, RETURN) = range(12)


class Compiler:
    """Compile one lambda (or the main expression) in its lexical scope."""

    def __init__(self, parent=None, param=None, recursive=None):
        self.code = []
        self.parent = parent
        self.locals = {}
        # Functions have two initial slots: argument and closure itself.
        self.depth = 0 if parent is None else 2
        if recursive is not None:
            self.locals[recursive] = 1
        if param is not None:
            self.locals[param] = 0
        self.free = {}
        self.capture_slots = []

    def resolve(self, x):
        # Local slots >= 0; captured slots encoded as bitwise complements.
        if x in self.locals:
            return self.locals[x]
        if x not in self.free:
            slot = self.parent.resolve(x)
            self.free[x] = ~len(self.capture_slots)
            self.capture_slots.append(slot)
        return self.free[x]

    def load(self, slot):
        self.code.append((LOCAL, slot) if slot >= 0 else (FREE, ~slot))

    def function(self, e, recursive=None):
        fn = Compiler(self, e[1], recursive)
        fn.expr(e[2], True)
        fn.code.append((RETURN, None))
        # Capture only the values that may be read; no mutable environment
        # shared with the creator. A recursive reference is local slot 1.
        if fn.capture_slots:
            for slot in fn.capture_slots:
                self.load(slot)
            self.code.append((CLOSURE, (fn.code, len(fn.capture_slots))))
        else:
            self.code.append((CONST, (fn.code, ())))

    def expr(self, e, tail):
        code = self.code
        k = e[0]
        if k == 'lit':
            code.append((CONST, e[1]))
        elif k == 'var':
            self.load(self.resolve(e[1]))
        elif k == 'lam':
